import{o as s,c as n,ag as i,j as e,k as a,g as r,a as o}from"./chunks/framework.B3amng90.js";const l="/abu-aigc-guide/screenshots/marketing.webp",d="/abu-aigc-guide/examples/marketing-preview.webp",g=["src","poster"],c=JSON.parse('{"title":"爆款 · 为商品制作短视频","description":"","frontmatter":{},"headers":[],"relativePath":"workflows/marketing.md","filePath":"workflows/marketing.md"}'),p={name:"workflows/marketing.md"},_=Object.assign(p,{setup(m){return(u,t)=>(s(),n("div",null,[t[0]||(t[0]=i('<h1 id="爆款-·-为商品制作短视频" tabindex="-1">爆款 · 为商品制作短视频 <a class="header-anchor" href="#爆款-·-为商品制作短视频" aria-label="Permalink to &quot;爆款 · 为商品制作短视频&quot;">​</a></h1><p>在侧栏打开 <strong>爆款</strong>。这节用一张去除商品标识的果汁杯样图，练习写脚本、选择视频模型和检查竖屏成片。</p><h2 id="_1-上传商品图并填写卖点" tabindex="-1">1. 上传商品图并填写卖点 <a class="header-anchor" href="#_1-上传商品图并填写卖点" aria-label="Permalink to &quot;1. 上传商品图并填写卖点&quot;">​</a></h2><p>选择 <strong>创意</strong>，在 <strong>商品</strong> 区上传 <a href="/abu-aigc-guide/examples/marketing-product.webp">果汁杯练习图</a>，再把下方描述填到输入区。实际创作可上传同一商品的 1–4 张图，补足正面、侧面和细节。</p><blockquote><p>薄荷绿色便携果汁杯，透明杯身带刻度，杯盖有提环。用干净明亮的厨房台面做背景，先展示杯子全貌，再给杯盖和提环一个近景，最后回到商品整体。保持杯身颜色和结构一致，字幕简短。</p></blockquote><p><a href="/abu-aigc-guide/screenshots/marketing.webp"><img src="'+l+'" alt="爆款创意入口的商品图、商品描述和底部设置" loading="lazy"></a></p><p>如果已有获准使用的参考视频或链接，可用 <strong>复刻</strong> 提取镜头节奏，再换成自己的商品素材和卖点。</p><h2 id="_2-选规格并写脚本" tabindex="-1">2. 选规格并写脚本 <a class="header-anchor" href="#_2-选规格并写脚本" aria-label="Permalink to &quot;2. 选规格并写脚本&quot;">​</a></h2><ol><li>选择投放平台，例如 <strong>抖音</strong>。选一个可用的视频模型，例如 <strong>muse-video</strong>，再把画幅设为 <strong>9:16</strong>。时长选模型支持的值，按实际时长分配镜头。</li><li>点击 <strong>写脚本</strong>。打开写好的脚本，核对商品描述、镜头顺序和字幕。去掉没有验证的性能、容量或功效描述。</li><li>可以用下表对照自己的脚本。样片时长 12 秒，每段 4 秒。</li></ol><table tabindex="0"><thead><tr><th>时间</th><th>画面</th><th>字幕示例</th></tr></thead><tbody><tr><td>0–4 秒</td><td>画面从干净台面引到商品全貌，杯子位于竖屏中央。</td><td>便携果汁杯</td></tr><tr><td>4–8 秒</td><td>镜头推近上半部，突出杯盖、翻盖和提环。</td><td>翻盖与提环</td></tr><tr><td>8–12 秒</td><td>回到整杯，保留杯身刻度和产品轮廓。</td><td>清晰杯身刻度</td></tr></tbody></table><h2 id="_3-出片并做发布前检查" tabindex="-1">3. 出片并做发布前检查 <a class="header-anchor" href="#_3-出片并做发布前检查" aria-label="Permalink to &quot;3. 出片并做发布前检查&quot;">​</a></h2><p>选一条脚本先出片。出片后在工作区中间的播放器从头看一遍，确认三段里的杯盖、提环和颜色一致，字幕可读且没遮住卖点。完成检查后可 <strong>下载成片</strong>，也可以 <strong>发到画布精修</strong>。</p><p><a href="/abu-aigc-guide/examples/marketing-preview.webp"><img src="'+d+'" alt="果汁杯营销样片的三段关键帧：商品全貌、杯盖细节、回到整体" loading="lazy"></a></p><p><em>关键帧和下方视频由同一张去标识商品图剪辑而成，用来对照脚本节奏和检查成片。</em></p>',14)),e("div",null,[e("video",{class:"guide-example-video",src:a(r)("/examples/marketing-demo.mp4"),poster:a(r)("/examples/marketing-poster.webp"),"aria-label":"果汁杯营销教程样片，12 秒竖屏，无声",controls:"",playsinline:"",preload:"none"},null,8,g)]),t[1]||(t[1]=e("p",null,[e("a",{href:"/abu-aigc-guide/examples/marketing-demo.mp4"},"打开或下载 12 秒竖屏教程样片（MP4）")],-1)),t[2]||(t[2]=e("p",null,[o("如果 "),e("strong",null,"写脚本"),o(" 按钮不可用，先确认商品图已上传完成，并且选中了可用的视频模型。")],-1))]))}});export{c as __pageData,_ as default};
